<?php declare(strict_types=1);require_once __DIR__.'/../includes/customer-auth.php';require_once __DIR__.'/../classes/Order.php';requireCustomerLogin();$c=(int)$_SESSION['customer_id'];$items=Order::cart($c);if(!$items){header('Location: cart');exit;}$err=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!verifyCsrfToken($_POST['csrf_token']??null))$err='نشست منقضی شده است.';else try{$id=Order::place($c,(string)($_POST['note']??''));header('Location: order?id='.$id);exit;}catch(Throwable $e){$err=$e->getMessage();}}$total=array_sum(array_map(fn($i)=>(int)$i['price']*(int)$i['quantity'],$items));?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/customer-auth.css"><title>تکمیل سفارش</title></head><body class="customer-auth"><main class="auth-card"><div class="auth-brand"><h1>تکمیل سفارش</h1><p>پرداخت آنلاین ندارد؛ سفارش برای تأیید ارسال می‌شود.</p></div><?php if($err):?><div class="auth-alert"><?=htmlspecialchars($err)?></div><?php endif;?><p>مبلغ کل: <b><?=number_format($total)?> تومان</b></p><form method="post" data-auth-form><input type="hidden" name="csrf_token" value="<?=csrfToken()?>"><div class="auth-field"><label>توضیحات سفارش</label><textarea class="auth-input" name="note" maxlength="500" rows="4"></textarea></div><button class="auth-submit">ثبت نهایی سفارش</button></form></main><script src="assets/js/customer-auth.js"></script></body></html>
